import type { RoomInfo, RoomInterface } from "@unomed/react-native-matrix-sdk";
import { useEffect, useState } from "react";

export const useRoomInfo = (room: RoomInterface | undefined) => {
  const [roomInfo, setRoomInfo] = useState<RoomInfo | null>(null);

  useEffect(() => {
    if (!room) return;
    room.roomInfo().then(setRoomInfo).catch(console.error);
    const handle = room.subscribeToRoomInfoUpdates({ call: setRoomInfo });
    return () => handle.cancel();
  }, [room]);

  return roomInfo;
};

